def cases():return json.loads(json.dumps(CASES))

@lru_cache(maxsize=1)
def _rows():return {r['key']:r for r in json.loads(FIXTURE.read_text(encoding='utf-8'))['rows']}

def packed(values):return [None if not math.isfinite(float(v)) else float(v) for v in values]

def expected(case):return json.loads(json.dumps(_rows()[case['key']]['expected']))

def independently_recalculate(case):
    row=_rows()[case['key']];a,b=case['inputs']
    if not row['draws']:return [None,None]
    try:return packed(interval(a,b,case['parameters']['eftype'],case['parameters'].get('confidence',.95),row['draws']))
    except (ValueError,ZeroDivisionError,OverflowError):return [None,None]

def production(case):
    from PyFLASH.stats_extra import effect_ci
    from PyFLASH.config import Config
    p=dict(case['parameters']);seed=case['seed'];kind=case['rng_kind']
    if kind=='generator':p['random_state']=np.random.default_rng(seed)
    elif kind=='random-state':p['random_state']=np.random.RandomState(seed)
    elif kind!='default':p['random_state']=seed
    with patch.object(Config,'EFFECT_CI_RANDOM_STATE',0):
        return packed(effect_ci(*case['inputs'],**p))

def equal(left,right):
    return len(left)==len(right) and np.allclose(np.asarray(left,dtype=float),np.asarray(right,dtype=float),rtol=1e-9,atol=1e-12,equal_nan=True)

def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_bytes()).hexdigest()!=fixture['reference_code_sha256']:raise ValueError('Bootstrap reference source changed')
    kernel=Path(__file__).with_name('bootstrap_reference.py')
    if hashlib.sha256(kernel.read_bytes()).hexdigest()!=fixture['independent_kernel_sha256']:raise ValueError('Independent bootstrap equations changed')
    if cases()!=[{k:r[k] for k in ['key','inputs','parameters','seed','rng_kind']} for r in fixture['rows']]:raise ValueError('Frozen bootstrap definitions changed')
    return fixture
